  {t:"mcq",src:"أسئلة سريعة",q:"كلمة «الصدق» تدل على معنى يُدرك بالعقل لا بالحس.",options:["صح","خطأ"],a:0,why:["az3ism"]},
  {t:"mcq",src:"أسئلة سريعة",q:"كلمة «الحديد» تدل على معنى مدرك بالعقل.",options:["صح","خطأ"],a:1,why:["az3ism"]}
